// Verifica se o n8n mandou algum item ou se veio vazio
const hasItems = items.length > 0 && Object.keys(items[0].json).length > 0;

// CENÁRIO: CLIENTE SEM COMPRAS
if (!hasItems) {
  return [{
    json: {
      result_text: "Este cliente foi localizado no sistema, porém não possui nenhum histórico de compras registrado.",
      sales_count: 0,
      raw_data: []
    }
  }];
}

// ------------------------------------------
// CENÁRIO: CLIENTE COM COMPRAS (Seu código original melhorado)
// ------------------------------------------

const rows = items.map(item => item.json);

// Formatador de Moeda (R$)
const money = new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' });
const formatDate = (dateString) => {
  if (!dateString) return 'Data N/D';
  const date = new Date(dateString);
  return date.toLocaleDateString('pt-BR');
};

// 1. Agrupamento
const vendasAgrupadas = {};
let clienteNome = "";

for (const row of rows) {
  if (!clienteNome) clienteNome = row.cliente || "Cliente";

  const idVenda = row.id_venda;

  if (!vendasAgrupadas[idVenda]) {
    vendasAgrupadas[idVenda] = {
      id: idVenda,
      data: formatDate(row.data_venda),
      itens: [],
      totalVenda: 0
    };
  }

  vendasAgrupadas[idVenda].itens.push({
    produto: row.produto,
    qtd: row.quantidade,
    unit: row.valor_unitario,
    total: row.valor_total
  });

  // Converte para número para evitar erros de soma se vier como string do banco
  vendasAgrupadas[idVenda].totalVenda += Number(row.valor_total || 0);
}

// 2. Construção do Texto
let textoFinal = `Cliente: ${clienteNome}\nHistórico de Compras:\n`;

for (const id in vendasAgrupadas) {
  const v = vendasAgrupadas[id];
  textoFinal += `\n--- Venda #${v.id} (${v.data}) ---\n`;
  v.itens.forEach(item => {
    textoFinal += `- ${item.qtd}x ${item.produto} (${money.format(item.unit)} un.)\n`;
  });
  textoFinal += `Total Venda: ${money.format(v.totalVenda)}\n`;
}

return [{
  json: {
    result_text: textoFinal,
    sales_count: Object.keys(vendasAgrupadas).length,
    raw_data: vendasAgrupadas
  }
}];
